    assert.ok(!r.g[0].troca && /contando a do dia 02\/10\/2026/.test(r.c[0].x), 'dia de repor lotado, sem agendar: reposição ' + r.c[0].x);
    r = await caso({ data: '2026-09-25', volta: '2026-09-29' });
