    const o = "{nome:'Mel', tutor:'Ana Souza', sexo:'Fêmea', itens:[{k:'ecto_p', nome:'Carrapaticida', vence:'2026-09-01', atrasado:true},{k:'col_p', nome:'Coleira', marca:'Seresto', vence:'2026-09-27', atrasado:false}]}";
