    assert.ok(/O ideal é aproveitar e fazer hoje mesmo\. Podemos\?/.test(m), m);
    assert.ok(!/O prazo já chegou/.test(m), 'mensagem mista não generaliza o prazo (QA)');
    const f = run('hojeFraseAntecipar(' + o + ", {itens:" + o + ".itens}, '2026-09-24')");
