    __elsMU={ciMedEmUso:{}, ciMedTudoIgual:{innerHTML:''}, ciMedEmUsoBox:{style:{}}, 'ci-med-status':{style:{}, textContent:''}, ciMeds:{querySelector:function(){ return {}; }}};
