    const na = run('despMedNaTela');
    if (/^bia__/.test(na || '')) { out.bia.push(hms647(t) + '/' + run('despMedAtualDia').slice(8) + '/' + (run('despMedNaoDar') ? 'Entendi' : 'ADIAR')); run('despMedSegundoBotao();'); }
