  assert.ok(h.indexOf('Como aceita a escovação?') > h.indexOf('Escova os dentes no Day Care?') && h.indexOf('Tem o kit dental aqui?') < h.indexOf('Troca de escova de hoje'), 'depois do Sim/Não e antes da troca de hoje');
