    Object.keys(__seed653.logs).forEach(function(d){ __put653('auaulandia/medicacao-log/'+d+'/${DE653.refKey}', __seed653.logs[d]); });
    __put653('daycare/cadastro/${DE653.refKey}', __seed653.ficha);
