    assert.ok(run('__AUD655').some((t) => /desfez o «Finalizar» da conversa sobre vermífugo, carrapaticida e coleira de Tico — motivo: "Toquei no FILHOt errado"/.test(t)), run('__AUD655').join('\n'));
