    run(`EST_TODAS.est_theo.status=''; EST_TODAS.est_theo.saida='';`);
    igual(vai(), false, 'sem a data de saída');
    run(`EST_TODAS.est_theo.saida='${TER652}'; delete EST_TODAS.est_theo.ficha.spa; EST_TODAS.est_theo.ficha.banho='Sim';`);
