    igual([run("orcFechado('2026-10-10')||''"), run(`orcFechado('${DOM652}')`), run(`orcFechado('${SEG652}')`), run(`orcFechado('${TER652}')||''`)], ['', 'domingo', 'Nossa Senhora Aparecida', '']);
